source='''from collections import Counter

def transform(grid):
    base = [row[:] for row in grid]
    out = [row[:] for row in grid]
    h, w = len(base), len(base[0])
    counts = Counter(v for row in base for v in row)
    bg = counts.most_common(1)[0][0]
    colors = [c for c in counts if c != bg]

    def longest(color, horizontal):
        best = 0
        if horizontal:
            for r in range(h):
                n = 0
                for c in range(w):
                    n = n + 1 if base[r][c] == color else 0
                    best = max(best, n)
        else:
            for c in range(w):
                n = 0
                for r in range(h):
                    n = n + 1 if base[r][c] == color else 0
                    best = max(best, n)
        return best

    # The continuous, straight segments are the rails. The other rare color
    # supplies marks that set the relative beam positions on each rail.
    bar = max(colors, key=lambda c: (max(longest(c, True), longest(c, False)), counts[c]))
    marks = [c for c in colors if c != bar]
    if not marks:
        return out
    dot = min(marks, key=lambda c: (counts[c], -max(longest(c, True), longest(c, False))))
    horizontal = longest(bar, True) >= longest(bar, False)

    # Collect the maximal rail segments, represented by their fixed coordinate
    # and half-open interval along the rail.
    segments = []
    if horizontal:
        for r in range(h):
            c = 0
            while c < w:
                if base[r][c] != bar:
                    c += 1
                    continue
                s = c
                while c < w and base[r][c] == bar:
                    c += 1
                if c - s >= 2:
                    segments.append((r, s, c))
    else:
        for c in range(w):
            r = 0
            while r < h:
                if base[r][c] != bar:
                    r += 1
                    continue
                s = r
                while r < h and base[r][c] == bar:
                    r += 1
                if r - s >= 2:
                    segments.append((c, s, r))
    if not segments:
        return out

    # Marks that lie in a rail's along-axis span encode offsets. Copy that
    # offset pattern to every parallel rail.
    offsets = set()
    for r in range(h):
        for c in range(w):
            if base[r][c] != dot:
                continue
            along = c if horizontal else r
            for fixed, s, e in segments:
                if s <= along < e:
                    offsets.add(along - s)
    if not offsets:
        offsets = set(range(max(e - s for _, s, e in segments)))

    for fixed, s, e in segments:
        for off in sorted(offsets):
            if not (s <= s + off < e):
                continue
            if horizontal:
                r, c = fixed, s + off
                dirs = ((-1, 0), (1, 0))
            else:
                r, c = s + off, fixed
                dirs = ((0, -1), (0, 1))
            for dr, dc in dirs:
                rr, cc = r + dr, c + dc
                while 0 <= rr < h and 0 <= cc < w:
                    v = base[rr][cc]
                    if v == dot:
                        out[rr][cc] = 4
                        break
                    if v != bg:
                        break
                    out[rr][cc] = dot
                    rr += dr
                    cc += dc
    return out
'''
